import { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { ArrowLeft, Clock, Calendar, X, Mail } from 'lucide-react';
import Header from './Header';
import Footer from './Footer';
import useSiteTheme from '../hooks/useSiteTheme';
import PrivacyPopup from './PrivacyPopup';
import AppStoreBadges from './AppStoreBadges';
import { useLocalizedPath } from '../i18n/paths';
import { useHreflangTags } from '../i18n/useHreflangTags';
import { stripLocalePrefix } from '../i18n/config';
import { truncateTitle, truncateDescription, setCanonical } from '../seo/meta';
import monitorIconUrl from '../public/monitor_icon_64.png';

function BlogContactPopup({ isOpen, onClose }) {
  const { t } = useTranslation('edb');
  useEffect(() => {
    if (typeof document === 'undefined') return;
    if (isOpen) {
      document.documentElement.style.overflow = 'hidden';
    } else {
      document.documentElement.style.overflow = '';
    }
    return () => { document.documentElement.style.overflow = ''; };
  }, [isOpen]);

  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/70" onClick={onClose}>
      <div
        className="legal-modal max-w-md w-full p-8 text-center"
        onClick={(e) => e.stopPropagation()}
      >
        <button onClick={onClose} aria-label={t('contact.close')} className="absolute top-4 right-4 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200"><X size={20} /></button>
        <div className="legal-modal-mark w-14 h-14 flex items-center justify-center mx-auto mb-4">
          <Mail className="w-7 h-7 text-white" />
        </div>
        <h3 className="text-xl font-bold text-slate-900 dark:text-white mb-2">{t('contact.title')}</h3>
        <p className="text-slate-600 dark:text-slate-300 mb-4 text-sm">{t('contact.description')}</p>
        <a href="mailto:contact@qod.ee" className="text-sky-600 dark:text-sky-400 font-semibold hover:underline">contact@qod.ee</a>
      </div>
    </div>
  );
}

export default function BlogLayout({
  title,
  description,
  date,
  readTime = '4 min read',
  isIndex = false,
  section = 'blog',
  tag,
  jsonLd = null,
  wide = false,
  languages = null,
  children,
}) {
  const { t, i18n } = useTranslation('edb');
  const localize = useLocalizedPath();
  useHreflangTags(languages);
  const sectionMeta = section === 'guides'
    ? { label: t('blogLayout.sectionGuides'), href: localize('/guides') }
    : { label: t('blogLayout.sectionBlog'), href: localize('/blog') };
  const { theme, toggleTheme: handleToggleTheme } = useSiteTheme();
  const [showContact, setShowContact] = useState(false);
  const [showPrivacy, setShowPrivacy] = useState(false);


  useEffect(() => {
    if (typeof document === 'undefined') return;
    const suffix = ' | ' + t('header.appName');
    const shortTitle = truncateTitle(title, 60);
    const shortDescription = truncateDescription(description, 155);
    document.title = truncateTitle(title, 70 - suffix.length) + suffix;
    const setMeta = (sel, val) => {
      const el = document.querySelector(sel);
      if (el) el.setAttribute('content', val);
    };
    setMeta('meta[name="description"]', shortDescription);
    setMeta('meta[property="og:title"]', shortTitle);
    setMeta('meta[property="og:description"]', shortDescription);
    // Not written in this language (an English-only article under /<lang>/): the English
    // page is the canonical one, so the copy is not indexed as a duplicate.
    const untranslated = languages && !languages.includes(i18n.language);
    setCanonical(untranslated ? stripLocalePrefix(window.location.pathname) : window.location.pathname);
  }, [title, description, t, i18n.language, languages ? languages.join(',') : '']);

  // Article structured data, removed again when navigating away
  const jsonLdText = jsonLd ? JSON.stringify(jsonLd) : null;
  useEffect(() => {
    if (typeof document === 'undefined' || !jsonLdText) return;
    const el = document.createElement('script');
    el.type = 'application/ld+json';
    el.textContent = jsonLdText;
    document.head.appendChild(el);
    return () => el.remove();
  }, [jsonLdText]);

  // Open contact/privacy popup from path if navigated directly
  useEffect(() => {
    const path = window.location.pathname;
    if (path.endsWith('/contact')) setShowContact(true);
    else if (path.endsWith('/privacy')) setShowPrivacy(true);
  }, []);

  return (
    <div className={`site-shell editorial-page min-h-screen ${isIndex ? 'editorial-index' : 'editorial-article'}`}>
      <Header theme={theme} onToggleTheme={handleToggleTheme} />

      <main id="main-content" className="editorial-main pt-16">
        {/* Breadcrumb */}
        <div className="breadcrumb-bar">
          <div className={`${wide ? 'max-w-6xl' : 'max-w-3xl'} mx-auto px-4 sm:px-6 lg:px-8 py-3`}>
            <nav className="breadcrumb-nav flex items-center gap-2 text-sm flex-wrap" aria-label="Breadcrumb">
              <a href={localize('/')} className="hover:text-sky-600 dark:hover:text-sky-400 transition-colors">{t('breadcrumb.home')}</a>
              <span>/</span>
              {isIndex ? (
                <span className="text-slate-700 dark:text-slate-300">{sectionMeta.label}</span>
              ) : (
                <>
                  <Link to={sectionMeta.href} className="hover:text-sky-600 dark:hover:text-sky-400 transition-colors">{sectionMeta.label}</Link>
                  <span>/</span>
                  <span className="text-slate-700 dark:text-slate-300 truncate">{title}</span>
                </>
              )}
            </nav>
          </div>
        </div>

        {/* Article */}
        <article className={`editorial-container ${wide ? 'editorial-container-wide max-w-6xl' : 'max-w-3xl'} mx-auto px-4 sm:px-6 lg:px-8 py-10 sm:py-14`}>
          {/* Article header */}
          <header className="editorial-hero mb-10">
            <div className="editorial-meta flex items-center gap-3 mb-4 flex-wrap">
              <span className="editorial-kicker inline-flex items-center gap-1.5 px-3 py-1 text-xs font-semibold">
                <img src={monitorIconUrl} alt="" className="w-3.5 h-3.5 rounded" width={14} height={14} loading="lazy" decoding="async" />
                {t('articleChrome.badgeLabel')}
              </span>
              {tag && (
                <span className="editorial-tag px-2.5 py-1 text-xs font-semibold">
                  {tag}
                </span>
              )}
              {date && (
                <span className="flex items-center gap-1 text-xs text-slate-500 dark:text-slate-400">
                  <Calendar className="w-3.5 h-3.5" />
                  {date}
                </span>
              )}
              {readTime && (
                <span className="flex items-center gap-1 text-xs text-slate-500 dark:text-slate-400">
                  <Clock className="w-3.5 h-3.5" />
                  {readTime}
                </span>
              )}
            </div>
            <h1 className="editorial-title text-3xl sm:text-4xl font-bold leading-tight mb-4">{title}</h1>
            <p className="editorial-dek text-lg leading-relaxed">{description}</p>
          </header>

          {/* Content */}
          <div className="editorial-content prose-custom">
            {children}
          </div>

          {/* Big CTA */}
          <div className="editorial-cta mt-14 p-8 text-center text-white">
            <img src={monitorIconUrl} alt="XeOS: External Display Browser" className="w-14 h-14 rounded-2xl shadow-lg mx-auto mb-4" width={56} height={56} loading="lazy" decoding="async" />
            <h3 className="text-2xl font-bold mb-2">{t('blogCta.title')}</h3>
            <p className="mb-6 max-w-md mx-auto text-sm leading-relaxed">{t('blogCta.description')}</p>
            <AppStoreBadges />
          </div>

          {/* Back */}
          <div className="editorial-back mt-10 pt-8 border-t flex items-center justify-between flex-wrap gap-4">
            {isIndex ? (
              <a href={localize('/')} className="inline-flex items-center gap-2 text-sky-600 dark:text-sky-400 hover:underline text-sm font-medium">
                <ArrowLeft className="w-4 h-4" />
                {t('articleChrome.backToHome')}
              </a>
            ) : (
              <Link to={sectionMeta.href} className="inline-flex items-center gap-2 text-sky-600 dark:text-sky-400 hover:underline text-sm font-medium">
                <ArrowLeft className="w-4 h-4" />
                {section === 'guides' ? t('articleChrome.allGuides') : t('articleChrome.allArticles')}
              </Link>
            )}
            <a
              href="https://apps.apple.com/us/app/external-display-browser/id6758286241"
              target="_blank"
              rel="noopener noreferrer"
              className="text-sm text-slate-500 dark:text-slate-400 hover:text-sky-600 dark:hover:text-sky-400 transition-colors"
            >
              {t('articleChrome.downloadOnAppStore')}
            </a>
          </div>
        </article>
      </main>

      <Footer
        openContactPopup={() => setShowContact(true)}
        openPrivacyPopup={() => setShowPrivacy(true)}
      />
      <BlogContactPopup isOpen={showContact} onClose={() => setShowContact(false)} />
      <PrivacyPopup
        isOpen={showPrivacy}
        onClose={() => setShowPrivacy(false)}
        openContactPopup={() => { setShowPrivacy(false); setShowContact(true); }}
        t={t}
      />
    </div>
  );
}
